{"code":"import pandas as pd, numpy as np, statsmodels.formula.api as smf
D=pd.read_csv('data/explore.csv')
y='species_richness'; xs=['canopy_cover','soil_moisture','elevation_m','road_dist_km','leaf_litter','temperature_c','slope_deg','nitrate','grazing_index','rainfall_mm']
for x in xs:
 d=D[[y,x,'region']].dropna(); m=smf.ols(f'{y} ~ {x} + C(region)',d).fit()
 print(x, 'n',len(d),'coef',round(m.params[x],3),'p',m.pvalues[x], 'r2',round(m.rsquared,3))"}
